package service

import (
	"encoding/base64"
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestDownloadOutputsFiltersByOutputKind(t *testing.T) {
	videoBytes, err := base64.StdEncoding.DecodeString("")
	if err != nil {
		t.Fatal(err)
	}
	comfy := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Query().Get("filename") == "final.mp4" {
			_, _ = w.Write(videoBytes)
			return
		}
		_, _ = w.Write([]byte("avif"))
	}))
	defer comfy.Close()

	s := NewServer(nil, nil, ServiceConfig{StorageMode: StorageModeLocal}, 1, t.TempDir(), nil)
	out, err := s.downloadOutputs(
		NewComfyClient(comfy.URL),
		"task-id",
		WorkflowConfig{ID: "wf", Mode: "i2v", OutputKind: "video"},
		map[string]any{
			"outputs": map[string]any{
				"1": map[string]any{"images": []any{map[string]any{"filename": "preview.avif", "type": "output"}}},
				"2": map[string]any{"videos": []any{map[string]any{"filename": "final.mp4", "type": "output"}}},
			},
		},
		nil,
	)
	if err != nil {
		t.Fatal(err)
	}
	if len(out) != 1 || out[0].Kind != "video" {
		t.Fatalf("outputs = %+v, want one video", out)
	}
}
